def _norm(title: str) -> str:
    return re.sub(r"\s+", " ", (title or "").strip())


_NORMALISED = {_norm(k): v for k, v in _DESCRIPTIONS.items()}


def description_for(title: str) -> str:
    """Return the brief UA description for a biblical book title, or '' if none."""
    return _NORMALISED.get(_norm(title), "")
